-- 82_v3.7에서_v3.8로.sql · 이미 v3.7로 만든 계정(교육원 공용 DB 포함)을 v3.8로 올리는 스크립트 (10/28)
-- 새로 만드는 계정은 이 파일 없이 01 → 02 → 03 만 실행하면 v3.8이 됨
-- v3.6 계정이면 83(v3.6→v3.7)을 먼저 실행하고 이것을 실행
--
-- v3.8에서 바뀐 것 - 기능명세서 v1.4 「5_결정 필요」 확정분 (10/28)
--   1) MEMBER: 금융 정보(소득·카드 내역) 저장 동의 일시·버전 FINANCE_AGREED_AT·FINANCE_VERSION (D-17 · 가입 때 별도 필수 체크박스 · 약관·개인정보 동의와 같은 방식)
--      → 이미 있는 회원은 개인정보 동의 일시·버전과 같은 값으로 채운 뒤 NOT NULL
--   2) INQUIRY: 문의 유형 INQUIRY_TYPE ERROR(오류)/QUESTION(문의)/ETC(기타) (D-12) → 이미 있는 문의는 QUESTION으로 채운 뒤 NOT NULL
--      문의 상태에 CHECKING(확인 중) 추가 (D-22 · 관리자 [확인중] 버튼) · 확인 중도 답변 3칸은 비어 있어야 함 (임시 안내 답변은 화면 고정 문구라 저장 안 함)
--   3) 새 테이블 STAT_FILE(통계 파일 · 원본·정제 파일은 저장 경로만) · GROUP_STAT(그룹 비교 통계 · 그룹 1개 = 1행 · 10개 항목 전부) (D-11)
--      → 국세통계 2024년 귀속 성별·연령대 12행 + 급여 구간 16행 = 28행 · 값이 어느 정제 csv에서 나왔는지 FILE_ID(FK) · 정제 csv가 어느 원본에서 나왔는지 ORIGIN_FILE_ID(FK)
--   탈퇴 30일 유예(D-21)는 구조 변경 없음 → 97_데이터정리.sql만 바뀜 (기존 WITHDRAWN_AT으로 30일 계산)
-- DB 구조 변경 있음 (ERD v3.8) · 테이블 18 → 20 · 칸 175 → 208 · CHECK 42 → 49 · UNIQUE 10 → 12 · 인덱스 23 → 25
-- 백엔드: 가입 INSERT에 FINANCE_AGREED_AT·FINANCE_VERSION · 문의 INSERT에 INQUIRY_TYPE 꼭 넣기 (빠지면 ORA-01400)

SET DEFINE OFF
SET SERVEROUTPUT ON

-- ─────────────────────────────────────────────
-- 0) 실행 전 확인 - 테이블 18 · 칸 175 · CHECK 42 · UNIQUE 10 · 인덱스 23 · 새 칸 0 · 새 테이블 0 이어야 함 (다르면 멈추고 알려 주세요)
-- ─────────────────────────────────────────────
SELECT (SELECT COUNT(*) FROM USER_TABLES) AS 테이블_수,
       (SELECT COUNT(*) FROM USER_TAB_COLUMNS WHERE TABLE_NAME IN (SELECT TABLE_NAME FROM USER_TABLES)) AS 칸_수,
       (SELECT COUNT(*) FROM USER_CONSTRAINTS WHERE CONSTRAINT_TYPE = 'C' AND CONSTRAINT_NAME LIKE 'CK\_%' ESCAPE '\') AS CHECK_수,
       (SELECT COUNT(*) FROM USER_CONSTRAINTS WHERE CONSTRAINT_TYPE = 'U') AS UNIQUE_수,
       (SELECT COUNT(*) FROM USER_INDEXES WHERE INDEX_NAME LIKE 'IX\_%' ESCAPE '\') AS 인덱스_수,
       (SELECT COUNT(*) FROM USER_TAB_COLUMNS WHERE (TABLE_NAME = 'MEMBER' AND COLUMN_NAME LIKE 'FINANCE\_%' ESCAPE '\') OR (TABLE_NAME = 'INQUIRY' AND COLUMN_NAME = 'INQUIRY_TYPE')) AS 새_칸,  -- 0
       (SELECT COUNT(*) FROM USER_TABLES WHERE TABLE_NAME IN ('STAT_FILE', 'GROUP_STAT')) AS 새_테이블,  -- 0
       (SELECT COUNT(*) FROM MEMBER) AS 회원_행,      -- 실행 후와 같아야 함
       (SELECT COUNT(*) FROM INQUIRY) AS 문의_행      -- 실행 후와 같아야 함
  FROM DUAL;

-- ─────────────────────────────────────────────
-- 1) MEMBER 금융 정보 저장 동의 (D-17) - 칸 추가 → 기존 회원 채우기 → NOT NULL
-- ─────────────────────────────────────────────
ALTER TABLE MEMBER ADD (FINANCE_AGREED_AT DATE, FINANCE_VERSION VARCHAR2(10));
UPDATE MEMBER SET FINANCE_AGREED_AT = PRIVACY_AGREED_AT, FINANCE_VERSION = PRIVACY_VERSION WHERE FINANCE_AGREED_AT IS NULL;
COMMIT;
ALTER TABLE MEMBER MODIFY (FINANCE_AGREED_AT NOT NULL, FINANCE_VERSION NOT NULL);

-- ─────────────────────────────────────────────
-- 2) INQUIRY 문의 유형 (D-12) · 확인 중 상태 (D-22)
-- ─────────────────────────────────────────────
ALTER TABLE INQUIRY ADD (INQUIRY_TYPE VARCHAR2(10));
UPDATE INQUIRY SET INQUIRY_TYPE = 'QUESTION' WHERE INQUIRY_TYPE IS NULL;
COMMIT;
ALTER TABLE INQUIRY MODIFY (INQUIRY_TYPE NOT NULL);
ALTER TABLE INQUIRY ADD CONSTRAINT CK_INQUIRY_TYPE CHECK (INQUIRY_TYPE IN ('ERROR', 'QUESTION', 'ETC'));
ALTER TABLE INQUIRY DROP CONSTRAINT CK_INQUIRY_STATUS;
ALTER TABLE INQUIRY ADD CONSTRAINT CK_INQUIRY_STATUS CHECK (STATUS IN ('WAITING', 'CHECKING', 'ANSWERED'));
ALTER TABLE INQUIRY DROP CONSTRAINT CK_INQUIRY_ANSWER;
ALTER TABLE INQUIRY ADD CONSTRAINT CK_INQUIRY_ANSWER CHECK ((STATUS IN ('WAITING', 'CHECKING') AND ANSWER IS NULL AND ANSWERED_AT IS NULL AND ANSWERED_BY IS NULL)
                                  OR (STATUS = 'ANSWERED' AND ANSWER IS NOT NULL AND ANSWERED_AT IS NOT NULL AND ANSWERED_BY IS NOT NULL));

-- ─────────────────────────────────────────────
-- 3) 그룹 비교 통계 테이블 2개 (D-11)
-- ─────────────────────────────────────────────
-- ▶ STAT_FILE: 그룹 비교 통계 파일 (v3.8 · D-11 · 원본·정제 파일은 DB에 넣지 않고 저장 경로만)
CREATE TABLE STAT_FILE (
  FILE_ID           NUMBER        NOT NULL,         -- 파일번호
  FILE_NAME         VARCHAR2(200) NOT NULL,         -- 파일 이름
  FILE_PATH         VARCHAR2(300) NOT NULL,         -- 저장 경로 (프로젝트 데이터 폴더 기준 상대 경로)
  FILE_KIND         VARCHAR2(10)  NOT NULL,         -- ORIGINAL(원본 · 국세통계포털에서 받은 그대로)/CLEANED(정제 · 06_비교통계_정리.py 결과)
  ORIGIN_FILE_ID    NUMBER,                         -- 정제 파일이 어느 원본에서 나왔는지 → STAT_FILE (원본이면 NULL)
  SOURCE_NAME       VARCHAR2(200) NOT NULL,         -- 출처 (국세통계 표 번호·이름)
  TAX_YEAR          NUMBER(4)     NOT NULL,         -- 통계 귀속 연도
  BASE_DATE         DATE,                           -- 원본 받은 날 (정제 파일은 NULL)
  DATA_ORIGIN       VARCHAR2(10)  DEFAULT 'COLLECTED' NOT NULL, -- 데이터 구분 (공공 통계라 COLLECTED)
  CREATED_AT        DATE          DEFAULT SYSDATE NOT NULL, -- 등록일
  CONSTRAINT PK_STAT_FILE PRIMARY KEY (FILE_ID),
  CONSTRAINT FK_STAT_FILE_ORIGIN FOREIGN KEY (ORIGIN_FILE_ID) REFERENCES STAT_FILE (FILE_ID),
  CONSTRAINT UQ_STAT_FILE_PATH UNIQUE (FILE_PATH),
  CONSTRAINT CK_STAT_FILE_KIND CHECK ((FILE_KIND = 'ORIGINAL' AND ORIGIN_FILE_ID IS NULL) OR (FILE_KIND = 'CLEANED' AND ORIGIN_FILE_ID IS NOT NULL)),  -- 정제 파일은 원본 연결 필수
  CONSTRAINT CK_STAT_FILE_ORIGIN CHECK (DATA_ORIGIN IN ('COLLECTED', 'GENERATED', 'INPUT'))
);

-- ▶ GROUP_STAT: 그룹 비교 통계 (v3.8 · D-11 · 「나와 비슷한 사람들은」 · 그룹 1개 = 1행 · 국세통계 2024년 귀속)
--   성별·연령대 그룹과 급여 구간 그룹은 원본 표가 달라 교차(예: 30대 남성 + 4천만대) 행은 없음
CREATE TABLE GROUP_STAT (
  STAT_ID           NUMBER        NOT NULL,         -- 통계번호
  FILE_ID           NUMBER        NOT NULL,         -- 이 값이 나온 정제 파일 → STAT_FILE
  TAX_YEAR          NUMBER(4)     NOT NULL,         -- 귀속 연도
  GROUP_TYPE        VARCHAR2(10)  NOT NULL,         -- GENDER_AGE(성별·연령대)/SALARY(급여 구간)
  GROUP_LABEL       VARCHAR2(50)  NOT NULL,         -- 그룹 이름 (정제 파일 표기 · 화면 표시용)
  GENDER            CHAR(1),                        -- 성별 M/F (성별·연령대 그룹만)
  AGE_MIN           NUMBER(3),                      -- 나이 시작(이상 · NULL = 하한 없음)
  AGE_MAX           NUMBER(3),                      -- 나이 끝(이하 · NULL = 상한 없음)
  SALARY_MIN        NUMBER(15),                     -- 총급여 구간 시작(초과 · 원)
  SALARY_MAX        NUMBER(15),                     -- 총급여 구간 끝(이하 · 원 · NULL = 상한 없음)
  PEOPLE_COUNT      NUMBER(12)    NOT NULL,         -- 인원
  TOTAL_SALARY_MIL  NUMBER(15)    NOT NULL,         -- 총급여 합계(백만 원)
  AVG_SALARY        NUMBER(15)    NOT NULL,         -- 1인당 총급여(원)
  AVG_DECIDED_TAX   NUMBER(15)    NOT NULL,         -- 1인당 결정세액(원)
  AVG_WITHHELD_TAX  NUMBER(15)    NOT NULL,         -- 1인당 기납부세액(원)
  AVG_REFUND_TAX    NUMBER(15)    NOT NULL,         -- 1인당 환급세액(원)
  AVG_PAYABLE_TAX   NUMBER(15)    NOT NULL,         -- 1인당 납부할세액(원)
  AVG_CARD_DEDUCTION NUMBER(15)   NOT NULL,         -- 1인당 신용카드등소득공제(원)
  AVG_RENT_CREDIT   NUMBER(15)    NOT NULL,         -- 1인당 월세세액공제(원)
  AVG_SME_REDUCTION NUMBER(15)    NOT NULL,         -- 1인당 중소기업취업자감면(원)
  CONSTRAINT PK_GROUP_STAT PRIMARY KEY (STAT_ID),
  CONSTRAINT FK_GROUP_STAT_FILE FOREIGN KEY (FILE_ID) REFERENCES STAT_FILE (FILE_ID),
  CONSTRAINT UQ_GROUP_STAT_GROUP UNIQUE (TAX_YEAR, GROUP_TYPE, GROUP_LABEL),
  CONSTRAINT CK_GROUP_STAT_TYPE CHECK (GROUP_TYPE IN ('GENDER_AGE', 'SALARY')),
  CONSTRAINT CK_GROUP_STAT_GENDER CHECK (GENDER IN ('M', 'F')),
  CONSTRAINT CK_GROUP_STAT_GROUP CHECK ((GROUP_TYPE = 'GENDER_AGE' AND GENDER IS NOT NULL AND SALARY_MIN IS NULL AND SALARY_MAX IS NULL)
                                    OR (GROUP_TYPE = 'SALARY' AND GENDER IS NULL AND AGE_MIN IS NULL AND AGE_MAX IS NULL)),  -- 그룹 종류에 맞는 칸만
  CONSTRAINT CK_GROUP_STAT_AMOUNT CHECK (PEOPLE_COUNT >= 0 AND TOTAL_SALARY_MIL >= 0 AND AVG_SALARY >= 0 AND AVG_DECIDED_TAX >= 0 AND AVG_WITHHELD_TAX >= 0
                                     AND AVG_REFUND_TAX >= 0 AND AVG_PAYABLE_TAX >= 0 AND AVG_CARD_DEDUCTION >= 0 AND AVG_RENT_CREDIT >= 0 AND AVG_SME_REDUCTION >= 0)
);

CREATE INDEX IX_STAT_FILE_ORIGIN ON STAT_FILE (ORIGIN_FILE_ID);
CREATE INDEX IX_GROUP_STAT_FILE ON GROUP_STAT (FILE_ID);
CREATE SEQUENCE SEQ_STAT_FILE START WITH 5 INCREMENT BY 1 NOCACHE;     -- 아래에서 1~4번을 넣으므로 5부터
CREATE SEQUENCE SEQ_GROUP_STAT START WITH 29 INCREMENT BY 1 NOCACHE;   -- 아래에서 1~28번을 넣으므로 29부터

